from __future__ import annotations

import json
import os
import re
import shutil
import zipfile
from dataclasses import dataclass
from pathlib import Path
from typing import Dict, Iterable, List, Optional, Tuple

import xml.etree.ElementTree as ET


TEMPLATE_HWPX = Path("/root/safety_audit_template.hwpx")
AUDIT_OVERVIEW_JSON = Path("/root/audit_overview.json")
CORRECTIVE_ACTIONS_JSON = Path("/root/corrective_actions.json")
OUT_HWPX = Path("/root/safety_audit_brief_final.hwpx")

WORK_DIR = Path("/tmp/hwpx_work")
EXTRACT_DIR = WORK_DIR / "work_extracted"


HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
NSMAP = {"hp": HWPML_NS}


PLACEHOLDER_RE = re.compile(r"\{\{([^}]+)\}\}")
DATE_YYYY_MM_DD_RE = re.compile(r"\b(\d{4})-(\d{2})-(\d{2})\b")


RISK_NOTE = {
    "High": "즉시조치",
    "Medium": "계획보완",
    "Low": "모니터링",
}


