    # Track paragraph elements whose text/tails were modified, so we can remove layout caches underneath.
    elem: ET.Element


def _iter_xml_files(root: Path) -> List[Path]:
    return sorted([p for p in root.rglob("*") if p.is_file() and p.suffix.lower() in {".xml", ".hpf"}])


def _load_json() -> Tuple[Dict[str, str], List[str]]:
    overview = json.loads(AUDIT_OVERVIEW_JSON.read_text(encoding="utf-8"))
    summary = overview.get("summary", {})

    actions_doc = json.loads(CORRECTIVE_ACTIONS_JSON.read_text(encoding="utf-8"))
    actions = actions_doc.get("immediate_actions", [])
    if not isinstance(actions, list):
        raise ValueError("corrective_actions.json immediate_actions must be a list")

    # Build mapping for base placeholders.
    mapping: Dict[str, str] = {}
    for k, v in summary.items():
        if v is None:
            continue
        mapping[str(k)] = str(v)

    # Risk tier formatting.
    risk = mapping.get("위험등급")
    if risk is not None:
        note = RISK_NOTE.get(risk)
        if note is None:
            raise ValueError(f"Unsupported 위험등급: {risk!r}")
        mapping["위험등급"] = f"{risk} ({note})"  # ASCII parentheses required

    # Inspection date conversion.
    raw_date = summary.get("점검일")
    if raw_date is not None:
        mapping["점검일"] = DATE_YYYY_MM_DD_RE.sub(r"\\1.\\2.\\3", str(raw_date))

    # Corrective actions: fill 조치1.. in order.
    for idx, item in enumerate(actions, start=1):
        mapping[f"조치{idx}"] = str(item)

    return mapping, [str(a) for a in actions]


def _replace_in_text(s: str, mapping: Dict[str, str]) -> Tuple[str, bool]:
    """Replace placeholders and date patterns in the provided string."""
    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1)
        if key in mapping:
            changed = True
            return mapping[key]
        return m.group(0)

    out = PLACEHOLDER_RE.sub(repl, s)

    # Global date normalization (covers any literal dates that may appear beyond placeholders).
    out2 = DATE_YYYY_MM_DD_RE.sub(r"\\1.\\2.\\3", out)
    if out2 != out:
        changed = True
    return out2, changed


def _find_para_ancestor(elem: ET.Element, parent_map: Dict[ET.Element, ET.Element]) -> Optional[ET.Element]:
    cur = elem
    while cur is not None:
        tag = cur.tag
        if tag == f"{{{HWPML_NS}}}p" or tag.endswith("}p") and tag.split("}", 1)[1] == "p":
            return cur
        cur = parent_map.get(cur)
    return None


def _remove_layout_cache_under(paragraph: ET.Element) -> int:
    """Remove hp:linesegarray and known variants under a paragraph."""
    removed = 0

    # Build a parent map within this paragraph subtree for removal.
    parent_map = {c: p for p in paragraph.iter() for c in list(p)}

    def local_name(tag: str) -> str:
        if tag.startswith("{"):
            return tag.split("}", 1)[1]
        return tag

    # Collect first, then remove, to avoid iterator invalidation.
    to_remove: List[ET.Element] = []
    for e in paragraph.iter():
        ln = local_name(e.tag).lower()
