        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray", "lineseg"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        # include camelCase variants, if any
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray", "linesegarray"}:
            to_remove.append(e)
        elif ln in {"linesegarray", "lineseg", "linesegarray", "linesegarray", "linesegarray", "linesegarray"}:
            to_remove.append(e)

    # Also match exact local names with case sensitivity.
    for e in paragraph.iter():
        ln = local_name(e.tag)
        if ln in {"linesegarray", "lineSegArray", "lineseg", "lineSeg"}:
            to_remove.append(e)

    # Deduplicate by id()
    seen = set()
    dedup: List[ET.Element] = []
    for e in to_remove:
        if id(e) in seen:
            continue
        seen.add(id(e))
        dedup.append(e)

    # Remove from parent
    for e in dedup:
        parent = parent_map.get(e)
        if parent is None:
            continue
        try:
            parent.remove(e)
            removed += 1
        except ValueError:
            pass

    return removed


def _process_xml_file(path: Path, mapping: Dict[str, str]) -> Tuple[bool, int]:
    """Returns (changed_any, removed_layout_count)."""
    tree = ET.parse(path)
    root = tree.getroot()

    # Parent map for ancestor resolution.
    parent_map: Dict[ET.Element, ET.Element] = {}
    for p in root.iter():
        for c in list(p):
            parent_map[c] = p

    modified_paras: Dict[int, ET.Element] = {}
    changed_any = False

    for elem in root.iter():
        if elem.text:
            new_text, changed = _replace_in_text(elem.text, mapping)
            if changed:
                elem.text = new_text
                changed_any = True
                para = _find_para_ancestor(elem, parent_map)
                if para is not None:
                    modified_paras[id(para)] = para

        if elem.tail:
            new_tail, changed = _replace_in_text(elem.tail, mapping)
            if changed:
                elem.tail = new_tail
                changed_any = True
                para = _find_para_ancestor(elem, parent_map)
                if para is not None:
                    modified_paras[id(para)] = para

    removed = 0
    if modified_paras:
        for para in modified_paras.values():
            removed += _remove_layout_cache_under(para)

    if changed_any or removed:
        tree.write(path, encoding="UTF-8", xml_declaration=True)

    return changed_any, removed


