    leftovers: List[Tuple[Path, str]] = []
    for p in _iter_xml_files(root):
        s = p.read_text(encoding="utf-8", errors="replace")
        if "{{" in s or "}}" in s:
            # capture a small snippet around first occurrence
            idx = s.find("{{")
            if idx == -1:
                idx = s.find("}}")
            start = max(0, idx - 40)
            end = min(len(s), idx + 80)
            leftovers.append((p, s[start:end]))

    if leftovers:
        msg = "\n".join([f"{p}: ...{snip}..." for p, snip in leftovers])
        raise AssertionError(f"Placeholders remain in output:\n{msg}")


def _repack_zip(src_dir: Path, out_path: Path) -> None:
    if out_path.exists():
        out_path.unlink()

    with zipfile.ZipFile(out_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
        # Preserve deterministic order: sort by relative path.
        for file_path in sorted([p for p in src_dir.rglob("*") if p.is_file()], key=lambda p: str(p.relative_to(src_dir))):
            arcname = str(file_path.relative_to(src_dir)).replace(os.sep, "/")
            z.write(file_path, arcname)


def main() -> None:
    if not TEMPLATE_HWPX.exists():
        raise FileNotFoundError(str(TEMPLATE_HWPX))

    mapping, actions = _load_json()

    # Fresh extract
    if EXTRACT_DIR.exists():
        shutil.rmtree(EXTRACT_DIR)
    EXTRACT_DIR.mkdir(parents=True, exist_ok=True)

    with zipfile.ZipFile(TEMPLATE_HWPX, "r") as z:
        z.extractall(EXTRACT_DIR)

    # Process all XML-like files
    removed_total = 0
    changed_files = 0
    for xml_path in _iter_xml_files(EXTRACT_DIR):
        changed, removed = _process_xml_file(xml_path, mapping)
        removed_total += removed
        if changed or removed:
            changed_files += 1

    _assert_no_placeholders(EXTRACT_DIR)

    _repack_zip(EXTRACT_DIR, OUT_HWPX)

    # Basic sanity: ensure output exists and is a zip.
    with zipfile.ZipFile(OUT_HWPX, "r") as z:
        z.testzip()

    print(f"Wrote {OUT_HWPX}")
    print(f"Changed files: {changed_files}, removed layout cache nodes: {removed_total}")


if __name__ == "__main__":
    main()

